"""pyarrow.parquet — iOS shim.

The bundled iOS pyarrow was built WITHOUT the Parquet C++ component
(no `pyarrow._parquet` extension, no libparquet), so the real
`pyarrow.parquet` can't load. It's imported at *module level* by
`datasets` / `evaluate` (arrow_reader, arrow_writer, iterable_dataset),
which otherwise use Arrow IPC (`.arrow`) — not Parquet — for JSON/CSV/
from_dict/map/split. This shim lets those import and their non-Parquet
paths work; anything that actually touches a `.parquet` file raises a
clear, actionable error instead of an ImportError at import time.

To get real Parquet on device, pyarrow must be rebuilt with
`-DARROW_PARQUET=ON` (+ the `_parquet` Cython ext) — a compiled-lib task.
"""

_MSG = ("pyarrow on iOS was built without Parquet support. Local JSON/CSV/"
        "Arrow and datasets.from_dict/from_pandas/map/split work; reading or "
        "writing .parquet files does not. Convert to JSON/CSV/Arrow, or "
        "rebuild pyarrow with ARROW_PARQUET=ON.")


class _NoParquet(RuntimeError):
    def __init__(self, *a, **k):
        super().__init__(_MSG)


def _unavailable(*_a, **_k):
    raise _NoParquet()


# Classes referenced at class-definition time in datasets (e.g.
# `_WRITER_CLASS = pq.ParquetWriter`) must EXIST as attributes; they only
# blow up if actually instantiated/called.
class ParquetWriter:
    def __init__(self, *a, **k): raise _NoParquet()

class ParquetFile:
    def __init__(self, *a, **k): raise _NoParquet()

class ParquetDataset:
    def __init__(self, *a, **k): raise _NoParquet()

class FileMetaData:  # returned by read_metadata
    def __init__(self, *a, **k): raise _NoParquet()

class ParquetSchema:
    def __init__(self, *a, **k): raise _NoParquet()


# Functions — importable, raise only when called.
read_table = _unavailable
write_table = _unavailable
read_metadata = _unavailable
read_schema = _unavailable
write_metadata = _unavailable
read_pandas = _unavailable


def __getattr__(name):
    # any other symbol datasets/evaluate reach for: importable, error on use
    if name.startswith("_"):
        raise AttributeError(name)
    return _unavailable
